pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Iteg {
        function setMaxTxPercent(uint256 maxTxPercent) external;
        function _maxTxAmount() external view returns (uint256);
        function owner() external view returns (address);
    }

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xc35B753d5F2e86cae7C42f755eb1812855aB10c0;
    address attacker = address(this);
    Iteg target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Iteg(TARGET);
        owner = target.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);

                // The owner calls setMaxTxPercent with 0 to freeze transfers
                target.setMaxTxPercent(0);

                vm.stopPrank();

                // Oracle Check: Verify that _maxTxAmount is now 0
                assertEq(target._maxTxAmount(), 0);
        assertEq(target._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

