pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TEGPAY {
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xc35B753d5F2e86cae7C42f755eb1812855aB10c0;
    address attacker = address(this);
    address constant OWNER = 0xBd51b6D98574327734C1621A7283778c5e6Af86e;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner address
        address currentOwner = TEGPAY(TARGET).owner();

        // Start impersonating the current owner
        vm.startPrank(currentOwner);
        TEGPAY(TARGET).setSwapAndLiquifyEnabled(false);
        vm.stopPrank();

        // Verify the state change
        bool enabled = TEGPAY(TARGET).swapAndLiquifyEnabled();
        require(enabled == false, "swapAndLiquifyEnabled should be false");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

